SELECT it.name, it.item_level AS ilvl, it.armor, it.block,
       it.stat_type1, it.stat_value1, it.stat_type2, it.stat_value2,
       sla.req_skill_value AS skill
FROM item_template it JOIN spell_template s ON s.effectItemType1 = it.entry
JOIN skill_line_ability sla ON sla.spell_id = s.entry
WHERE it.entry IN (90140,90141,90142,90143,90144,90145,90146,90147,90148,90149,90150,90151,90152,90153,90154,90155,90156,90157) ORDER BY it.item_level, it.name;
